import { isBindingObject, expression, Ref, stringTemplate, getSelector, computable } from "cx/data";
import { getCurrentInstance } from "cx/ui";
import { isObject, hasFunctionAtKey, hasStringAtKey, isArray, isFunction, isString } from "cx/util";

function useStore() {
	return getCurrentInstance().store;
}
function useStoreMethods() {
	return getCurrentInstance().store.getMethods();
}
function ref(info) {
	if (isObject(info)) {
		if (isBindingObject(info)) return useStore().ref(info.bind, info.defaultValue);
		if (hasFunctionAtKey(info, "get")) return info;
		if (hasFunctionAtKey(info, "memoize")) return info;
		if (hasStringAtKey(info, "expr")) {
			let store = useStore();
			let selector = expression(info.expr).memoize();
			return new Ref({
				get: () => selector(store.getData()),
				set: info.set,
			});
		}
		if (hasStringAtKey(info, "tpl")) {
			let store = useStore();
			let selector = stringTemplate(info.tpl).memoize();
			return new Ref({
				get: () => selector(store.getData()),
				set: info.set,
			});
		}
	}
	return getSelector(info);
}

function useEffect(callback) {
	let destroyCallback = callback();
	if (destroyCallback) getCurrentInstance().subscribeOnDestroy(destroyCallback);
}
function useCleanup(cleanupCallback) {
	let unsubscribe = getCurrentInstance().subscribeOnDestroy(cleanupCallback);
	return () => {
		unsubscribe();
		cleanupCallback();
	};
}

function useInterval(callback, timeout) {
	let timer = setInterval(callback, timeout);
	return useCleanup(() => {
		clearInterval(timer);
	});
}

function addExploreCallback(callback) {
	let instance = getCurrentInstance();
	if (!instance.computables) instance.computables = [];
	instance.computables.push(callback);
	return () => {
		if (instance.computables) {
			instance.computables = instance.computables.filter((cb) => cb !== callback);
		}
	};
}
function useTrigger(args, callback, autoRun) {
	if (!isArray(args)) throw new Error("First argument to useTrigger should be an array.");
	let store = useStore();
	let selector = computable(...args, callback).memoize(!autoRun && store.getData());
	return addExploreCallback(selector);
}

let key = 0;
function useState(defaultValue) {
	let instance = getCurrentInstance();
	let storeKey = "_state" + ++key;
	instance.setState({
		[storeKey]: defaultValue,
	});
	return new Ref({
		get: () => instance.state[storeKey],
		set: (value) => {
			instance.setState({
				[storeKey]: value,
			});
			return true;
		},
	});
}

function createLocalStorageRef(key) {
	let store = useStore();
	return new Ref({
		get() {
			let json = localStorage.getItem(key);
			if (!json) return localStorage.hasOwnProperty(key) ? null : undefined;
			return JSON.parse(json);
		},
		set(value) {
			if (value === undefined) localStorage.removeItem(key);
			else localStorage.setItem(key, JSON.stringify(value));
			store.meta.version++;
			store.notify();
			return true;
		},
	});
}

function resolveCallback(callback, instance) {
	if (isFunction(callback)) return callback;
	if (isString(callback)) {
		if (!instance) instance = getCurrentInstance();
		return (...args) => instance.invokeControllerMethod(callback, ...args);
	}
	return undefined;
}

function invokeCallback(instance, callback, ...args) {
	if (isString(callback)) return instance.invokeControllerMethod(callback, ...args);
	if (isFunction(callback)) return callback(...args);
}

export {
	addExploreCallback,
	createLocalStorageRef,
	invokeCallback,
	ref,
	resolveCallback,
	useCleanup,
	useEffect,
	useInterval,
	useState,
	useStore,
	useStoreMethods,
	useTrigger,
};
